/* Global focus styles */
*:focus {
  outline: none; /* reset default */
}
*:focus-visible {
  outline: 3px solid #005A9C;
  outline-offset: 2px;
  border-radius: 2px;
}

// When deleting a list item, move focus to the next item or previous
function deleteItem(item) {
  const next = item.nextElementSibling || item.previousElementSibling;
  item.remove();
  if (next) next.focus();
}
